-- Fixed closing-fill attribution. Episode counts overlap when exits have mixed roles.
-- Original native roles and exact application intent IDs; not a quote-based execution-shortfall estimate.
-- Run on verified read replica; one-account cohort validated in performance.sql.
BEGIN READ ONLY; SET LOCAL statement_timeout='25s';
WITH tx AS MATERIALIZED (SELECT a.*,i.cycle_id,i.protection FROM accounting_transactions a JOIN intents i USING(intent_id) WHERE occurred_at>='2026-11-16' AND occurred_at<'2026-11-26'),
entry AS MATERIALIZED (SELECT s.cycle_id,s.decision_hash,s.document->'targetPlan'->'intentTargets'->0->>'side' AS entry_side,s.document->'strategyDecision'->'exitPolicy'->'plans' AS plans FROM autonomous_cycle_shadow_decisions s WHERE s.cycle_id IN(SELECT DISTINCT cycle_id FROM tx)),
closing AS MATERIALIZED (SELECT t.*,e.decision_hash AS entry_hash,e.plans->t.symbol->'levels' AS levels,f.broker_order_id FROM tx t JOIN entry e USING(cycle_id) JOIN fills f ON f.event_id=t.broker_event_id WHERE t.side<>e.entry_side),
roles AS MATERIALIZED (SELECT o.broker_order_id,o.account_id,min(o.order_type) AS order_type,bool_or(o.parent_broker_order_id IS NOT NULL) AS native_child,count(distinct (o.order_type,o.parent_broker_order_id)) AS role_variants FROM orders o WHERE o.broker_order_id IN(SELECT broker_order_id FROM closing) GROUP BY o.broker_order_id,o.account_id),
docs AS MATERIALIZED (SELECT cycle_id,document->'document' AS doc FROM autonomous_cycle_paper_closures WHERE cycle_id IN(SELECT DISTINCT cycle_id FROM closing) UNION ALL SELECT cycle_id,document->'document' AS doc FROM autonomous_cycle_paper_close_replans WHERE cycle_id IN(SELECT DISTINCT cycle_id FROM closing)),
reasons AS MATERIALIZED (SELECT cycle_id,id.value AS intent_id,string_agg(distinct doc->'strategyDecision'->>'reason',',') AS reason,bool_or(coalesce((doc->'strategyDecision'->'evidence'->'portfolio'->>'profitExitRequested')::boolean,false)) AS profit_requested FROM docs CROSS JOIN LATERAL jsonb_array_elements_text(doc->'orderedIntentIds') id GROUP BY cycle_id,id.value),
classified AS MATERIALIZED (SELECT c.*,o.role_variants,r.reason,r.profit_requested,
CASE WHEN o.order_type='LIMIT' AND (o.native_child OR (c.protection->>'_tag'='Oco' AND c.protection->>'entryDecisionHash'=c.entry_hash AND c.protection->>'stopPriceMicros'=c.levels->>'stopPriceMicros' AND c.protection->>'stopLimitPriceMicros'=c.levels->>'stopLimitPriceMicros' AND c.protection->>'profitLimitPriceMicros'=c.levels->>'profitLimitPriceMicros')) THEN 'NATIVE_TARGET' WHEN o.order_type='STOP_LIMIT' AND o.native_child THEN 'NATIVE_STOP' ELSE 'APPLICATION:'||COALESCE(r.reason,'UNMATCHED')||CASE WHEN r.profit_requested THEN ':PROFIT_REQUESTED' ELSE '' END END AS exit_role
FROM closing c LEFT JOIN roles o USING(broker_order_id,account_id) LEFT JOIN reasons r USING(cycle_id,intent_id))
SELECT 'exits',(occurred_at AT TIME ZONE 'America/New_York')::date AS session_day,exit_role,count(*) AS closing_fills,count(distinct cycle_id) AS episodes_touched,sum(realized_pnl_micros)/1e6 AS attributed_gross_pnl,count(*)FILTER(WHERE role_variants<>1) AS ambiguous_order_roles FROM classified GROUP BY session_day,exit_role ORDER BY session_day,exit_role;
COMMIT;
